const getProspectOperationType = (methodName: string) => methodName.startsWith("get") ? "GET" : "POST";

const getProspectStatusTone = (status: string) => {
  const normalized = status.toLowerCase();
  if (normalized === "success") return "bg-emerald-100 text-emerald-700";
  if (normalized === "failed") return "bg-rose-100 text-rose-700";
  return "bg-amber-100 text-amber-700";
};

const ProspectSyncStatusPanel = ({
  logs,
  loading,
  refreshing,
  operationFilter,
  statusFilter,
  onOperationFilterChange,
  onStatusFilterChange,
  onRefresh,
}: {
  logs: ProspectSyncLog[];
  loading: boolean;
  refreshing: boolean;
  operationFilter: "all" | "post" | "get";
  statusFilter: "all" | "pending" | "success" | "failed";
  onOperationFilterChange: (value: "all" | "post" | "get") => void;
  onStatusFilterChange: (value: "all" | "pending" | "success" | "failed") => void;
  onRefresh: () => void;
}) => {
  const filteredLogs = logs.filter((log) => {
    const operationType = getProspectOperationType(log.methodName).toLowerCase();
    if (operationFilter !== "all" && operationType !== operationFilter) return false;
    if (statusFilter !== "all" && log.status.toLowerCase() !== statusFilter) return false;
    return true;
  });

  const summary = logs.reduce(
    (acc, log) => {
      const operationType = getProspectOperationType(log.methodName);
      acc.total += 1;
      if (operationType === "POST") acc.post += 1;
      if (operationType === "GET") acc.get += 1;
      const normalizedStatus = log.status.toLowerCase();
      if (normalizedStatus === "success") acc.success += 1;
      else if (normalizedStatus === "failed") acc.failed += 1;
      else acc.pending += 1;
      return acc;
    },
    { total: 0, post: 0, get: 0, success: 0, failed: 0, pending: 0 }
  );

  return (
    <div className="card">
      <div className="flex flex-col gap-4 border-b border-slate-100 p-6 lg:flex-row lg:items-center lg:justify-between">
        <div>
          <h3 className="text-lg font-bold text-slate-900">Prospect Sync Status</h3>
          <p className="text-sm text-slate-500">In-app status for every Prospect POST and GET operation.</p>
        </div>
        <div className="flex flex-wrap gap-2">
          <select className="input-field py-1.5 text-sm" value={operationFilter} onChange={(e) => onOperationFilterChange(e.target.value as "all" | "post" | "get")}>
            <option value="all">All Operations</option>
            <option value="post">POST Only</option>
            <option value="get">GET Only</option>
          </select>
          <select className="input-field py-1.5 text-sm" value={statusFilter} onChange={(e) => onStatusFilterChange(e.target.value as "all" | "pending" | "success" | "failed")}>
            <option value="all">All Statuses</option>
            <option value="pending">Pending</option>
            <option value="success">Success</option>
            <option value="failed">Failed</option>
          </select>
          <button onClick={onRefresh} className="btn-secondary flex items-center gap-2 text-sm" disabled={refreshing}>
            {refreshing ? <Loader2 size={16} className="animate-spin" /> : <History size={16} />}
            Refresh Prospect Reads
          </button>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 border-b border-slate-100 p-6 md:grid-cols-6">
        {[
          { label: "Total", value: summary.total, tone: "text-slate-900" },
          { label: "POST", value: summary.post, tone: "text-blue-700" },
          { label: "GET", value: summary.get, tone: "text-cyan-700" },
          { label: "Success", value: summary.success, tone: "text-emerald-700" },
          { label: "Pending", value: summary.pending, tone: "text-amber-700" },
          { label: "Failed", value: summary.failed, tone: "text-rose-700" },
        ].map((item) => (
          <div key={item.label} className="rounded-2xl border border-slate-100 bg-slate-50 p-4">
            <p className="text-[11px] font-bold uppercase tracking-wide text-slate-500">{item.label}</p>
            <p className={`mt-1 text-2xl font-bold ${item.tone}`}>{item.value}</p>
          </div>
        ))}
      </div>

      <div className="divide-y divide-slate-100">
        {loading && (
          <div className="flex items-center gap-3 p-6 text-sm text-slate-500">
            <Loader2 size={16} className="animate-spin" />
            Loading Prospect sync activity...
          </div>
        )}
        {!loading && filteredLogs.length === 0 && (
          <div className="p-6 text-sm text-slate-500">No Prospect sync activity matched the selected filters.</div>
        )}
        {!loading && filteredLogs.map((log) => {
          const operationType = getProspectOperationType(log.methodName);
          return (
            <div key={log.id} className="p-6">
              <div className="flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
                <div className="space-y-2">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className={`rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-widest ${operationType === "POST" ? "bg-blue-100 text-blue-700" : "bg-cyan-100 text-cyan-700"}`}>
                      {operationType}
                    </span>
                    <p className="font-semibold text-slate-900">{log.methodName}</p>
                    <span className={`rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-widest ${getProspectStatusTone(log.status)}`}>
                      {log.status}
                    </span>
                  </div>
                  <p className="text-xs text-slate-500">
                    Record: {log.recordType || "—"} #{log.recordId || "—"} • Attempts: {log.attempts}
                  </p>
                  {log.errorMessage && <p className="text-xs text-rose-600">{log.errorMessage}</p>}
                </div>
                <div className="text-xs text-slate-400">
                  {log.createdAt ? new Date(log.createdAt).toLocaleString() : "N/A"}
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

const triggerDownload = (filename: string, content: string, mimeType = "text/plain;charset=utf-8") => {
  const blob = new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
};

const escHtml = (value?: string | null) =>
  (value || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");

const pdfFmt = (value?: string | null) => {
  if (!value) return "N/A";
  const ts = Date.parse(value);
  if (Number.isNaN(ts)) return value;
  return new Date(ts).toLocaleString([], { year: "numeric", month: "long", day: "numeric", hour: "2-digit", minute: "2-digit" });
};

const buildTenderPdfHtml = (tender: Tender) => {
  const row = (label: string, value?: string | null, accent = "") =>
    `<div class="row"><span class="label">${escHtml(label)}</span><span class="value ${accent}">${escHtml(value || "N/A")}</span></div>`;

  const list = (label: string, values?: string[]) =>
    `<div class="row"><span class="label">${escHtml(label)}</span><span class="value">${values && values.length ? values.map(v => `<span class="chip">${escHtml(v)}</span>`).join("") : "N/A"}</span></div>`;

  const chip = (label: string, value: string | number | undefined | null) =>
    `<div class="stat"><div class="stat-label">${escHtml(label)}</div><div class="stat-value">${escHtml(value == null ? "N/A" : String(value))}</div></div>`;

  const isSingleStageCombined = tender.procurementWorkflow === "combined" && !tender.eoiDeadline;
  const stages = [
    { label: "EOI (Stage 1)", value: tender.eoiDeadline, show: !isSingleStageCombined },
    { label: "Combined Submission (Stage 2)", value: tender.technicalDeadline, show: tender.procurementWorkflow !== "sequential" },
    { label: "Technical (Stage 2)", value: tender.technicalDeadline, show: tender.procurementWorkflow === "sequential" },
    { label: "Financial (Stage 3)", value: tender.financialDeadline, show: tender.procurementWorkflow === "sequential" },
  ].filter(s => s.show).map(s => row(s.label, s.value)).join("");

  const deadlineSection = tender.eoiDeadline || tender.technicalDeadline || tender.financialDeadline
    ? `<div class="section-title">Deadlines & Schedule</div><div class="section">${row("Overall Closing Deadline", tender.deadline)}${stages}</div>`
    : "";

  const requirements = [
    ["Tender Security", tender.tenderSecurityRequired === true ? "Required" : tender.tenderSecurityRequired === false ? "Not Required" : "N/A"],
    ["Bidders Schedule Purchase", tender.biddersSchedulePurchase === true ? "Required" : "Not Required"],
    ["Cooling-Off Period", tender.coolingOffDays ? `${tender.coolingOffDays} days` : "N/A"],
  ].map(([l, v]) => row(l, v)).join("");

  return `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8" />
<title>${escHtml(tender.name)}</title>
<style>
  * { box-sizing: border-box; }
  body { font-family: 'Segoe UI', -apple-system, Helvetica, Arial, sans-serif; color: #1e293b; margin: 0; padding: 0; line-height: 1.5; }
  .page { padding: 40px 44px 32px; }
  .cover { background: linear-gradient(135deg, #065f46 0%, #047857 55%, #059669 100%); color: #fff; border-radius: 14px; padding: 34px 34px 28px; margin-bottom: 28px; }
  .cover .eyebrow { font-size: 11px; text-transform: uppercase; letter-spacing: 0.18em; color: #a7f3d0; font-weight: 700; }
  .cover h1 { margin: 10px 0 6px; font-size: 25px; line-height: 1.25; font-weight: 700; color: #fff; }
  .cover .ref { color: #d1fae5; font-size: 13px; letter-spacing: 0.02em; }
  .cover .meta { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 18px; }
  .cover .pill { background: rgba(255,255,255,0.14); color: #ecfdf5; border-radius: 999px; padding: 4px 12px; font-size: 11px; font-weight: 600; }
  .badge { display: inline-block; padding: 3px 12px; border-radius: 999px; background: #d1fae5; color: #065f46; font-size: 11px; font-weight: 700; }
  .summary { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; margin-bottom: 30px; }
  .stat { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 14px 16px; }
  .stat-label { font-size: 10px; text-transform: uppercase; letter-spacing: 0.08em; color: #64748b; font-weight: 700; }
  .stat-value { margin-top: 4px; font-size: 16px; font-weight: 700; color: #0f766e; word-break: break-word; }
  .section-title { display: flex; align-items: center; gap: 10px; font-size: 12px; text-transform: uppercase; letter-spacing: 0.12em; color: #0f766e; font-weight: 700; margin: 30px 0 12px; }
  .section-title::after { content: ""; flex: 1; height: 1px; background: #e2e8f0; }
  .section { border: 1px solid #e2e8f0; border-radius: 12px; overflow: hidden; }
  .row { display: flex; border-bottom: 1px solid #f1f5f9; }
  .row:last-child { border-bottom: none; }
  .label { width: 260px; flex-shrink: 0; background: #f8fafc; padding: 12px 16px; font-size: 12px; font-weight: 700; color: #475569; }
  .value { flex: 1; padding: 12px 16px; font-size: 13px; white-space: pre-wrap; word-break: break-word; }
  .value.strong { font-weight: 700; color: #0f172a; }
  .chip { display: inline-block; background: #ecfdf5; color: #047857; border: 1px solid #a7f3d0; border-radius: 6px; padding: 2px 8px; font-size: 12px; font-weight: 600; margin: 1px 4px 1px 0; }
  .note { white-space: pre-wrap; }
  .footer { border-top: 1px solid #e2e8f0; margin-top: 34px; padding-top: 14px; color: #94a3b8; font-size: 11px; display: flex; justify-content: space-between; }
  @media print { body { padding: 0; } .cover { -webkit-print-color-adjust: exact; print-color-adjust: exact; } .badge, .chip, .stat { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }
</style>
</head>
<body>
  <div class="page">
    <div class="cover">
      <div class="eyebrow">Tender Invitation</div>
      <h1>${escHtml(tender.name)}</h1>
      <div class="ref">Reference Number: ${escHtml(tender.referenceNumber)}</div>
      <div class="meta">
        <span class="pill">${escHtml(tender.department || "Department N/A")}</span>
        <span class="pill">${escHtml(tender.category || "Category N/A")}</span>
        <span class="pill">${escHtml(tender.procurementMethod || "Method N/A")}</span>
      </div>
    </div>

    <div class="summary">
      ${chip("Status", tender.status)}
      ${chip("Overall Deadline", tender.deadline ? pdfFmt(tender.deadline) : "N/A")}
      ${chip("Funding Source", tender.fundingSource)}
      ${chip("Budget (M)", tender.budget?.toLocaleString())}
    </div>

    <div class="section-title">Tender Information</div>
    <div class="section">
      ${row("Status", `<span class="badge">${escHtml(tender.status)}</span>`)}
      ${row("Procurement Workflow", tender.procurementWorkflow === "sequential" ? "Sequential (EOI → Technical → Financial)" : tender.procurementWorkflow === "eoi_combined" ? "EOI → Combined" : isSingleStageCombined ? "Combined" : "Combined (EOI + Technical/Financial)")}
      ${row("Application Type", tender.applicationType)}
      ${row("Department", tender.department)}
      ${row("Category", tender.category)}
      ${row("Procurement Method", tender.procurementMethod)}
      ${row("Place for Opening (Venue)", tender.placeForOpening)}
      ${row("Address for Documents", tender.addressForDocument)}
      ${row("Address for Security", tender.addressForSecurity)}
      ${row("Bidders Eligibility", tender.biddersEligibility)}
      ${row("Time for Completion", tender.timeForCompletion)}
      ${row("Invited By", tender.invitedBy)}
      ${row("Bidding Currency", tender.biddingCurrency)}
      ${row("Funding Source", tender.fundingSource)}
      ${row("Stage Type", tender.stageType)}
    </div>

    ${deadlineSection}

    <div class="section-title">Technical Requirements</div>
    <div class="section">
      ${list("Technology Types", tender.technologyTypes)}
      ${list("Target Districts", tender.targetDistricts)}
      ${row("Target Site Type", tender.targetSiteType)}
      ${row("Approximate Installation Target", tender.approximateInstallationTarget !== undefined && tender.approximateInstallationTarget !== null ? String(tender.approximateInstallationTarget) : undefined)}
      ${row("Minimum Service Tier", tender.minimumServiceTier)}
      ${row("Technical Weight", tender.technicalWeight !== undefined ? `${tender.technicalWeight}%` : undefined)}
      ${row("Financial Weight", tender.financialWeight !== undefined ? `${tender.financialWeight}%` : undefined)}
      ${row("Technical Threshold", tender.technicalThreshold !== undefined ? `${tender.technicalThreshold}%` : undefined)}
    </div>

    <div class="section-title">Additional Requirements</div>
    <div class="section">${requirements}</div>

    ${tender.preTenderMeetingInfo ? `<div class="section-title">Pre-Tender Meeting</div><div class="section"><div class="row"><div class="value note">${escHtml(tender.preTenderMeetingInfo)}</div></div></div>` : ""}
    ${tender.instruction ? `<div class="section-title">Instructions</div><div class="section"><div class="row"><div class="value note">${escHtml(tender.instruction)}</div></div></div>` : ""}
    ${tender.contactDetails ? `<div class="section-title">Contact Information</div><div class="section"><div class="row"><div class="value note">${escHtml(tender.contactDetails)}</div></div></div>` : ""}

    <div class="footer">
      <span>${escHtml(tender.referenceNumber)}</span>
      <span>Generated ${pdfFmt(new Date().toISOString())}</span>
    </div>
  </div>
</body>
</html>`;
};

const downloadTenderPdf = (tender: Tender) => {
  const html = buildTenderPdfHtml(tender);
  const win = window.open("", "_blank", "width=860,height=1100");
  if (!win) {
    triggerDownload(`tender_${tender.referenceNumber || tender.id}.html`, html, "text/html;charset=utf-8");
    return;
  }
  win.document.open();
  win.document.write(html);
  win.document.close();
  win.focus();
  win.print();
};

const isConnectivityError = (raw: string) => {
  const lower = raw.toLowerCase();
  return (
    lower.includes("failed to fetch") ||
    lower.includes("timed out") ||
    lower.includes("networkerror")
  );
};

const isNotificationError = (msg: string) => {
  const lower = msg.toLowerCase();
  if (lower.includes("session expired") || lower.includes("session has expired")) return true;
  if (lower.startsWith("failed to ") || lower.startsWith("cannot ")) return true;
  if (lower.includes(" not valid") || lower.includes(" permission")) return true;
  return false;
};

const isServerError = (err: any) =>
  Number(err?.status) >= 500 || /^HTTP (5\d\d) /.test(String(err?.message || ""));

// DRF renders a field-keyed error dict as "key: message". These are machine keys that add
// nothing for the user, so drop the prefix and show the sentence. Listed explicitly rather
// than matched generically so a legitimate message ("note: ...") is never mangled.
const API_ERROR_KEY_PREFIXES = ["required_documents", "signed_file", "annexes"];

const toFriendlyApiMessage = (raw: string): string => {
  const cleaned = raw
    .replace(/^http\s+\d+\s+[a-z ]+:\s*/i, "")
    .replace(/^error:\s*/i, "")
    .trim();
  const withoutKey = cleaned.replace(
    new RegExp(`^(?:${API_ERROR_KEY_PREFIXES.join("|")}):\\s*`, "i"),
    "",
  ).trim();
  const finalText = withoutKey || cleaned;
  if (!finalText || finalText.length > 220) return "";
  return finalText;
};

const BID_ERROR_MAP: Record<string, string> = {
  "Only vendors can submit bids.": "Only vendor accounts can submit bids. Please log in with a vendor account.",
  "Your vendor account is suspended or blacklisted. Bid submission is disabled.": "Your vendor account has been suspended or blacklisted. Please contact the RBF Management Team for assistance.",
  "Complete pre-qualification first": "Please complete the pre-qualification process before submitting bids.",
  "Tender is not open for bidding.": "This tender is no longer accepting bids.",
  "Bidding deadline has passed.": "The bidding deadline has passed. No further submissions can be accepted for this tender.",
  "Only shortlisted vendors can submit Stage 2 proposals.": "Only shortlisted vendors are eligible to submit Stage 2 proposals.",
  "You have already submitted a bid for this tender.": "You have already submitted a bid for this tender.",
  "Submitted bids are locked. Create or edit a draft before final submission.": "This bid has been submitted and cannot be edited directly. Please create or edit a draft instead.",
  "Only draft or revision-required bids can be submitted.": "Only draft or revision-required bids can be submitted for final review.",
  "Technical and financial proposal files are required for site-specific bids.": "Please upload the Technical Proposal and Financial Proposal documents before submitting.",
  "BOQ file is required for site-specific bids.": "Please upload the Bill of Quantities document before submitting.",
  "Bill of Quantities is required for site-specific submissions.": "A Bill of Quantities is required for Stage 2 submissions.",
  "O&M strategy summary is required for site-specific submissions.": "An O&M strategy summary is required for Stage 2 submissions.",
  "PAYGO platform is required when PAYGO is offered.": "Please select a PAYGO platform when offering PAYGO payment terms.",
  "Minimum daily payment is required when PAYGO is offered.": "Please enter the minimum daily payment amount when offering PAYGO payment terms.",
  "Collection method is required when PAYGO is offered.": "Please select a collection method when offering PAYGO payment terms.",
  "You must confirm the inclusion commitment before submitting.": "Please confirm the inclusion commitment checkbox before submitting.",
  "At least 1 project site is required.": "Please add at least one project site before submitting.",
  "Site name, district, primary beneficiary type, and number of households are required before submitting.": "Please complete all required site fields (name, district, beneficiary type, and households).",
  "Latitude and longitude are required before submitting.": "GPS coordinates are required for Stage 2 sites. Please enter latitude and longitude or use \"Use My Location\".",
  "Site coordinates must fall within Lesotho.": "The site coordinates are outside Lesotho. Please verify the latitude and longitude.",
};

const friendlyBidError = (raw: string): string => {
  const cleaned = toFriendlyApiMessage(raw);
  if (!cleaned) return "";
  for (const [pattern, friendly] of Object.entries(BID_ERROR_MAP)) {
    if (cleaned.includes(pattern) || raw.includes(pattern)) return friendly;
  }
  const fieldStripped = cleaned
    .replace(/^(tender|detail|sites|boq_items|boq_details|concept_note|technical_proposal_file|financial_proposal_file|boq_file|tech_tier|om_strategy_summary|status|system_configuration|non_field_errors):\s*/i, "")
    .trim();
  if (fieldStripped.length > 3 && fieldStripped !== cleaned && !fieldStripped.includes("[object ")) return fieldStripped;
  if (cleaned.includes("[object ") || raw.includes("[object ")) return "";
  return cleaned;
};

