const Login = ({
  onLogin,
  onRegisterClick,
  onViewPublic,
  infoMessage,
  sessionExpiredMessage,
}: {
  onLogin: (username: string, password: string) => Promise<void>;
  onRegisterClick: () => void;
  onViewPublic: () => void;
  infoMessage?: string | null;
  sessionExpiredMessage?: string | null;
}) => {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showForgotModal, setShowForgotModal] = useState(false);
  const [forgotIdentifier, setForgotIdentifier] = useState("");
  const [forgotSubmitting, setForgotSubmitting] = useState(false);
  const [forgotResult, setForgotResult] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");

    if (!username || !password) {
      setError("Please enter both username and password.");
      return;
    }

    try {
      setIsSubmitting(true);
      await onLogin(username.trim(), password.trim());
    } catch (err: any) {
      const raw = String(err?.message || "");
      const lower = raw.toLowerCase();
      if (lower.includes("pending approval")) {
        setError("Your account is pending approval. Please contact an administrator.");
      } else if (lower.includes("no active account")) {
        setError("Invalid username or password.");
      } else if (lower.includes("throttled") || lower.includes("too many requests")) {
        setError("Too many login attempts. Please wait a minute and try again.");
      } else if (isConnectivityError(raw)) {
        setError(`Cannot connect to backend (${API_BASE}). Start backend and try again.`);
      } else {
        const friendly = toFriendlyApiMessage(raw);
        setError(friendly || "Login failed. Please verify your credentials and try again.");
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="max-w-md w-full bg-white rounded-3xl shadow-xl p-8 border border-slate-100"
      >
        <div className="text-center mb-8">
          <div className="w-16 h-16 rounded-2xl bg-emerald-600 flex items-center justify-center text-white font-bold text-3xl mx-auto mb-4 shadow-lg shadow-emerald-600/20">
            R
          </div>
          <h2 className="text-2xl font-bold text-slate-900">Welcome Back</h2>
          <p className="text-slate-500">Sign in to the RBF Digital Platform</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          {infoMessage && (
            <div className="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-xs font-medium text-emerald-700">
              {infoMessage}
            </div>
          )}

          {sessionExpiredMessage && (
            <div className="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-xs font-medium text-amber-700 flex items-start gap-2">
              <AlertTriangle size={16} className="mt-0.5 shrink-0" />
              <span>{sessionExpiredMessage}</span>
            </div>
          )}

          <div className="space-y-1">
            <label className="text-sm font-bold text-slate-700 ml-1">Username</label>
            <div className="relative">
              <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input
                type="text"
                autoComplete="username"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                className="input-field pl-10"
                placeholder="Enter your username"
              />
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-sm font-bold text-slate-700 ml-1">Password</label>
            <div className="relative">
              <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input
                type="password"
                autoComplete="current-password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="input-field pl-10"
                placeholder="********"
              />
            </div>
          </div>

          {error && <p className="text-rose-600 text-xs font-medium ml-1">{error}</p>}

          <div className="flex items-center justify-between py-2">
            <label className="flex items-center gap-2 cursor-pointer">
              <input type="checkbox" className="rounded border-slate-300 text-emerald-600 focus:ring-emerald-600" />
              <span className="text-xs text-slate-600">Remember me</span>
            </label>
            <button
              type="button"
              onClick={() => { setShowForgotModal(true); setForgotResult(null); setForgotIdentifier(""); }}
              className="text-xs font-bold text-emerald-600 hover:text-emerald-700"
            >
              Forgot Password?
            </button>
          </div>

          <button
            type="submit"
            disabled={isSubmitting}
            className="w-full btn-primary py-3 rounded-xl shadow-lg shadow-emerald-600/20 disabled:opacity-60 disabled:cursor-not-allowed"
          >
            {isSubmitting ? "Signing In..." : "Sign In"}
          </button>
        </form>

        <div className="mt-8 pt-6 border-t border-slate-100 space-y-4">
          <button
            onClick={onViewPublic}
            className="w-full py-3 px-4 bg-emerald-50 text-emerald-700 rounded-xl font-bold text-sm flex items-center justify-center gap-2 hover:bg-emerald-100 transition-colors"
          >
            <Eye size={16} />
            View Public Portal
          </button>
          <p className="text-sm text-slate-500">
            Are you a Vendor?{" "}
            <button onClick={onRegisterClick} className="font-bold text-emerald-600 hover:text-emerald-700">
              Register your organization first
            </button>
          </p>
        </div>
      </motion.div>

      {showForgotModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="w-full max-w-sm rounded-2xl bg-white p-6 shadow-xl border border-slate-100"
          >
            <h3 className="text-lg font-bold text-slate-900">Reset Password</h3>
            <p className="mt-1 text-sm text-slate-500">
              Enter your username or email address. If an account exists, a reset link will be sent to your email.
            </p>
            {!forgotResult ? (
              <div className="mt-4 space-y-3">
                <input
                  type="text"
                  value={forgotIdentifier}
                  onChange={(e) => setForgotIdentifier(e.target.value)}
                  className="input-field w-full"
                  placeholder="Username or email"
                  autoFocus
                  onKeyDown={(e) => {
                    if (e.key === "Enter" && forgotIdentifier.trim() && !forgotSubmitting) {
                      e.preventDefault();
                      document.getElementById("forgot-submit-btn")?.click();
                    }
                  }}
                />
                <div className="flex justify-end gap-2">
                  <button
                    onClick={() => setShowForgotModal(false)}
                    className="btn-secondary text-xs"
                  >
                    Cancel
                  </button>
                  <button
                    id="forgot-submit-btn"
                    onClick={async () => {
                      if (!forgotIdentifier.trim()) return;
                      setForgotSubmitting(true);
                      try {
                        const result = await requestPasswordReset(forgotIdentifier.trim());
                        let msg = "If an account with that username or email exists, a reset link has been sent to the email on file.";
                        if (result.resetUrl) msg += `\n\nDebug reset link: ${result.resetUrl}`;
                        if (result.emailError) msg += `\n\nEmail error: ${result.emailError}`;
                        setForgotResult(msg);
                      } catch (err: any) {
                        setForgotResult("If an account with that username or email exists, a reset link has been sent to the email on file.");
                      } finally {
                        setForgotSubmitting(false);
                      }
                    }}
                    disabled={forgotSubmitting || !forgotIdentifier.trim()}
                    className="btn-primary text-xs"
                  >
                    {forgotSubmitting ? "Sending..." : "Send Reset Link"}
                  </button>
                </div>
              </div>
            ) : (
              <div className="mt-4 space-y-3">
                <div className="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-xs text-emerald-700 whitespace-pre-wrap">
                  {forgotResult}
                </div>
                <button
                  onClick={() => setShowForgotModal(false)}
                  className="w-full btn-primary text-xs"
                >
                  Close
                </button>
              </div>
            )}
          </motion.div>
        </div>
      )}
    </div>
  );
};

const ResetPassword = () => {
  const token = new URLSearchParams(window.location.search).get("token") || "";
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [result, setResult] = useState<{ success: boolean; message: string } | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!token) {
      setResult({ success: false, message: "Invalid reset link. No token found." });
      return;
    }
    if (newPassword.length < 8) {
      setResult({ success: false, message: "Password must be at least 8 characters." });
      return;
    }
    if (newPassword !== confirmPassword) {
      setResult({ success: false, message: "Passwords do not match." });
      return;
    }
    setSubmitting(true);
    try {
      await confirmResetPassword(token, newPassword);
      setResult({ success: true, message: "Password has been reset successfully. You can now sign in." });
    } catch (err: any) {
      setResult({ success: false, message: String(err?.message || "Invalid or expired reset link.") });
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="max-w-md w-full bg-white rounded-3xl shadow-xl p-8 border border-slate-100"
      >
        <div className="text-center mb-8">
          <div className="w-16 h-16 rounded-2xl bg-emerald-600 flex items-center justify-center text-white font-bold text-3xl mx-auto mb-4 shadow-lg shadow-emerald-600/20">
            R
          </div>
          <h2 className="text-2xl font-bold text-slate-900">Reset Password</h2>
          <p className="text-slate-500">Enter your new password below</p>
        </div>

        {!result ? (
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-1">
              <label className="text-sm font-bold text-slate-700 ml-1">New Password</label>
              <input
                type="password"
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                className="input-field w-full"
                placeholder="At least 8 characters"
                autoFocus
              />
            </div>
            <div className="space-y-1">
              <label className="text-sm font-bold text-slate-700 ml-1">Confirm Password</label>
              <input
                type="password"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                className="input-field w-full"
                placeholder="Re-enter your new password"
              />
            </div>
            <button
              type="submit"
              disabled={submitting || !newPassword || !confirmPassword}
              className="w-full btn-primary py-3 rounded-xl shadow-lg shadow-emerald-600/20 disabled:opacity-60 disabled:cursor-not-allowed"
            >
              {submitting ? "Resetting..." : "Reset Password"}
            </button>
          </form>
        ) : (
          <div className="space-y-4">
            <div className={`rounded-xl border px-4 py-3 text-xs ${result.success ? "border-emerald-200 bg-emerald-50 text-emerald-700" : "border-rose-200 bg-rose-50 text-rose-700"}`}>
              {result.message}
            </div>
            {result.success && (
              <a
                href="/login"
                onClick={(e) => { e.preventDefault(); window.history.replaceState({ __app: "rbf-spa" }, "", "/login"); window.location.reload(); }}
                className="w-full btn-primary py-3 rounded-xl text-center block"
              >
                Go to Sign In
              </a>
            )}
            {!result.success && (
              <button
                onClick={() => setResult(null)}
                className="w-full btn-primary py-3 rounded-xl"
              >
                Try Again
              </button>
            )}
          </div>
        )}
      </motion.div>
    </div>
  );
};

const ForcePasswordReset = ({
  user,
  onComplete,
  onLogout,
}: {
  user: User;
  onComplete: (user: User) => void;
  onLogout: () => void;
}) => {
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [error, setError] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    if (!password || password.length < 8) {
      setError("Password must be at least 8 characters.");
      return;
    }
    if (password !== confirm) {
      setError("Passwords do not match.");
      return;
    }
    try {
      setIsSubmitting(true);
      const updated = await changeOwnPassword(password);
      onComplete(updated);
    } catch (err: any) {
      const friendly = toFriendlyApiMessage(String(err?.message || ""));
      setError(friendly || "Unable to update password. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-white rounded-3xl shadow-xl p-8 border border-slate-100">
        <div className="text-center mb-6">
          <div className="w-14 h-14 rounded-2xl bg-emerald-600 flex items-center justify-center text-white font-bold text-2xl mx-auto mb-4 shadow-lg shadow-emerald-600/20">
            R
          </div>
          <h2 className="text-2xl font-bold text-slate-900">Set a New Password</h2>
          <p className="text-slate-500">You must change your temporary password before continuing.</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-1">
            <label className="text-sm font-bold text-slate-700 ml-1">New Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="input-field"
              placeholder="At least 8 characters"
              minLength={8}
              required
            />
          </div>
          <div className="space-y-1">
            <label className="text-sm font-bold text-slate-700 ml-1">Confirm Password</label>
            <input
              type="password"
              value={confirm}
              onChange={(e) => setConfirm(e.target.value)}
              className="input-field"
              placeholder="Re-enter password"
              minLength={8}
              required
            />
          </div>
          {error && <p className="text-rose-600 text-xs font-medium ml-1">{error}</p>}
          <button
            type="submit"
            disabled={isSubmitting}
            className="w-full btn-primary py-3 rounded-xl shadow-lg shadow-emerald-600/20 disabled:opacity-60 disabled:cursor-not-allowed"
          >
            {isSubmitting ? "Updating..." : "Update Password"}
          </button>
        </form>

        <div className="mt-6 text-center">
          <button onClick={onLogout} className="text-xs font-bold text-slate-500 hover:text-slate-700">
            Sign out
          </button>
        </div>
      </div>
    </div>
  );
};

// --- Pages ---

const PublishApprovals = ({ onOpenTender }: { onOpenTender?: (tenderId: string) => void }) => {
  const [pending, setPending] = useState<Tender[]>([]);
  const [loading, setLoading] = useState(true);
  const [actionTenderId, setActionTenderId] = useState<string | null>(null);
  const [notesMap, setNotesMap] = useState<Record<string, string>>({});
  const [reasonOpen, setReasonOpen] = useState(false);
  const [activeTender, setActiveTender] = useState<Tender | null>(null);
  const [deciding, setDeciding] = useState<"approve" | "reject" | "changes_requested">("approve");
  const [error, setError] = useState<string | null>(null);
  const [toast, setToast] = useState<string | null>(null);

  const actionError = (err: any, fallback: string) => {
    const raw = String(err?.message || "");
    if (isConnectivityError(raw)) return `Cannot connect to the backend (${API_BASE}).`;
    return toFriendlyApiMessage(raw) || fallback;
  };

  const load = async () => {
    try {
      setLoading(true);
      const rows = await fetchPendingPublishApprovals();
      setPending(rows);
    } catch (err: any) {
      setError(actionError(err, "Failed to load pending publish approvals."));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void load();
  }, []);

  const confirmDecision = async () => {
    if (!activeTender) return;
    setActionTenderId(activeTender.id);
    setError(null);
    try {
      if (deciding === "approve") {
        const updated = await approvePublish(activeTender.id, notesMap[activeTender.id]);
        setPending((prev) => prev.filter((t) => t.id !== updated.id));
        setToast("Publish approval granted. The RBF can now publish this tender.");
      } else if (deciding === "changes_requested") {
        const updated = await requestPublishChanges(activeTender.id, notesMap[activeTender.id]);
        setPending((prev) => prev.filter((t) => t.id !== updated.id));
        setToast("Changes requested. The RBF has been sent back to Draft to revise and resubmit.");
      } else {
        const updated = await rejectPublish(activeTender.id, notesMap[activeTender.id]);
        setPending((prev) => prev.filter((t) => t.id !== updated.id));
        setToast("Publish request rejected.");
      }
      setReasonOpen(false);
      setActiveTender(null);
    } catch (err: any) {
      setError(actionError(err, "Failed to process approval."));
    } finally {
      setActionTenderId(null);
    }
  };

  const openDecision = (tender: Tender, decision: "approve" | "reject" | "changes_requested") => {
    setActiveTender(tender);
    setDeciding(decision);
    setNotesMap((m) => ({ ...m, [tender.id]: m[tender.id] ?? "" }));
    setError(null);
    setReasonOpen(true);
  };

  return (
    <div className="space-y-6">
      {toast && (
        <div className="flex items-center justify-between gap-4 p-4 bg-emerald-50 rounded-xl border border-emerald-200">
          <p className="text-sm text-emerald-800 font-medium">{toast}</p>
          <button onClick={() => setToast(null)} className="text-emerald-600 hover:text-emerald-800">
            <X size={18} />
          </button>
        </div>
      )}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Publish Approvals</h1>
          <p className="text-sm text-slate-500 mt-1">Review tenders that the RBF has requested to publish.</p>
        </div>
        <button onClick={() => void load()} className="btn-secondary flex items-center gap-2" disabled={loading}>
          <RefreshCw className={loading ? "animate-spin" : ""} size={16} /> Refresh
        </button>
      </div>

      {error && <div className="p-4 bg-rose-50 rounded-xl border border-rose-200 text-sm text-rose-700">{error}</div>}

      {loading ? (
        <div className="card p-10 text-center text-sm text-slate-500">Loading pending approvals...</div>
      ) : pending.length === 0 ? (
        <div className="card p-12 text-center">
          <ShieldCheck size={40} className="mx-auto text-emerald-300 mb-3" />
          <p className="font-semibold text-slate-700">No pending publish approvals</p>
          <p className="text-sm text-slate-500 mt-1">Tenders requested for publication by the RBF will appear here.</p>
        </div>
      ) : (
        <div className="space-y-4">
          {pending.map((tender) => (
            <div key={tender.id} className="card p-5">
              <div className="flex flex-wrap items-start justify-between gap-4">
                <div className="space-y-1">
                  <div className="flex items-center gap-3">
                    <h3 className="font-bold text-slate-900">{tender.name}</h3>
                    <span className="badge bg-sky-100 text-sky-700">{tender.status}</span>
                  </div>
                  <p className="text-xs font-mono text-slate-500">{tender.referenceNumber}</p>
                </div>
                <div className="flex gap-2">
                  {onOpenTender && (
                    <button onClick={() => onOpenTender(tender.id)} className="btn-secondary text-sm py-1.5">
                      View Tender
                    </button>
                  )}
                  <button
                    onClick={() => openDecision(tender, "approve")}
                    disabled={actionTenderId === tender.id}
                    className="btn-primary text-sm py-1.5 bg-emerald-600 hover:bg-emerald-700 disabled:opacity-60"
                  >
                    Approve
                  </button>
                  <button
                    onClick={() => openDecision(tender, "changes_requested")}
                    disabled={actionTenderId === tender.id}
                    className="btn-secondary text-sm py-1.5 border-orange-200 text-orange-700 hover:bg-orange-50 disabled:opacity-60"
                  >
                    Request Changes
                  </button>
                  <button
                    onClick={() => openDecision(tender, "reject")}
                    disabled={actionTenderId === tender.id}
                    className="btn-secondary text-sm py-1.5 border-rose-200 text-rose-700 hover:bg-rose-50 disabled:opacity-60"
                  >
                    Reject
                  </button>
                </div>
              </div>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-4 text-sm">
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Department</p>
                  <p className="font-medium text-slate-700 mt-0.5">{tender.department || "N/A"}</p>
                </div>
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Category</p>
                  <p className="font-medium text-slate-700 mt-0.5">{tender.category || "N/A"}</p>
                </div>
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Budget</p>
                  <p className="font-medium text-slate-700 mt-0.5">M {tender.budget?.toLocaleString() ?? "N/A"}</p>
                </div>
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Requested</p>
                  <p className="font-medium text-slate-700 mt-0.5">
                    {tender.publishApprovalRequestedAt
                      ? new Date(tender.publishApprovalRequestedAt).toLocaleString()
                      : "N/A"}
                  </p>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {reasonOpen && activeTender && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl p-6 w-full max-w-md shadow-2xl">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-bold text-slate-900">
                {deciding === "approve" ? "Approve Publish" : deciding === "changes_requested" ? "Request Changes" : "Reject Publish"}
              </h3>
              <button onClick={() => { setReasonOpen(false); setActiveTender(null); }} className="p-1 hover:bg-slate-100 rounded-lg">
                <X size={20} className="text-slate-500" />
              </button>
            </div>
            <p className="text-sm text-slate-600 mb-4 font-medium">{activeTender.name}</p>
            {deciding === "changes_requested" && (
              <p className="text-xs text-orange-700 bg-orange-50 border border-orange-100 rounded-lg px-3 py-2 mb-4">
                The tender goes back to the RBF as a Draft with a "Changes Requested" status (instead of a flat rejection) so they know to revise and resubmit it for approval.
              </p>
            )}
            <div>
              <label className="text-sm font-bold text-slate-700 mb-2 block">
                {deciding === "approve" ? "Approval Notes (optional)" : deciding === "changes_requested" ? "What needs to change? (recommended)" : "Reason for Rejection (optional)"}
              </label>
              <textarea
                className="input-field min-h-[90px]"
                value={notesMap[activeTender.id] ?? ""}
                onChange={(e) => setNotesMap((m) => ({ ...m, [activeTender.id]: e.target.value }))}
                placeholder={
                  deciding === "approve" ? "Add any notes for the RBF..." :
                  deciding === "changes_requested" ? "Describe what the RBF needs to fix before resubmitting..." :
                  "Explain why the tender should not be published..."
                }
              />
            </div>
            <div className="flex gap-3 pt-4">
              <button onClick={() => setReasonOpen(false)} className="btn-secondary flex-1">Cancel</button>
              <button
                onClick={() => void confirmDecision()}
                disabled={actionTenderId === activeTender.id}
                className={`flex-1 btn-primary disabled:opacity-60 ${
                  deciding === "approve" ? "bg-emerald-600 hover:bg-emerald-700" :
                  deciding === "changes_requested" ? "bg-orange-600 hover:bg-orange-700" :
                  "bg-rose-600 hover:bg-rose-700"
                }`}
              >
                {actionTenderId === activeTender.id
                  ? deciding === "approve" ? "Approving..." : deciding === "changes_requested" ? "Sending back..." : "Rejecting..."
                  : deciding === "approve" ? "Approve" : deciding === "changes_requested" ? "Request Changes" : "Reject"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const IntentToAwardApprovals = ({ onOpenTender }: { onOpenTender?: (tenderId: string) => void }) => {
  const [pending, setPending] = useState<IntentToAwardRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [busyId, setBusyId] = useState<string | null>(null);
  const [notesMap, setNotesMap] = useState<Record<string, string>>({});
  const [active, setActive] = useState<IntentToAwardRequest | null>(null);
  const [deciding, setDeciding] = useState<"approve" | "changes_requested" | "reject">("approve");
  const [error, setError] = useState<string | null>(null);
  const [toast, setToast] = useState<string | null>(null);

  const actionError = (err: any, fallback: string) => {
    const raw = String(err?.message || "");
    if (isConnectivityError(raw)) return `Cannot connect to the backend (${API_BASE}).`;
    return toFriendlyApiMessage(raw) || fallback;
  };

  /**
   * A decision that times out is ambiguous, not failed: the server may well have applied
   * it and only the response was slow. Rather than tell the Super Admin "cannot connect"
   * and invite a second click, re-sync the queue — if the request is gone from it the
   * decision landed, and if it is still there it genuinely did not. Re-clicking is safe
   * either way, because `approve_intent_award` re-reads the request under a row lock and
   * only acts on a PENDING one.
   */
  const decisionError = async (err: any, fallback: string, decidedId: string) => {
    const raw = String(err?.message || "");
    if (!isConnectivityError(raw)) {
      setError(actionError(err, fallback));
      return;
    }
    setError("The server did not confirm in time. Checking whether the decision was applied...");
    try {
      const fresh = await fetchPendingIntentToAwardApprovals();
      setPending(fresh);
      if (fresh.some((r) => r.id === decidedId)) {
        setActive(null);
        setError("The request is still awaiting your decision — nothing was applied. Please try again.");
      } else {
        setActive(null);
        setToast("The decision was applied. The server was slow to confirm it, so the queue has been refreshed for you.");
      }
    } catch {
      setError(
        "The server did not confirm in time and could not be reached to check. Refresh the page to see whether the decision was applied before clicking again."
      );
    }
  };

  const load = async () => {
    try {
      setLoading(true);
      setPending(await fetchPendingIntentToAwardApprovals());
    } catch (err: any) {
      setError(actionError(err, "Failed to load pending intent to award approvals."));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void load();
  }, []);

  const openDecision = (request: IntentToAwardRequest, decision: typeof deciding) => {
    setActive(request);
    setDeciding(decision);
    setNotesMap((m) => ({ ...m, [request.id]: m[request.id] ?? "" }));
    setError(null);
  };

  const confirmDecision = async () => {
    if (!active) return;
    const request = active;
    const notes = notesMap[request.id] ?? "";
    setBusyId(request.id);
    setError(null);
    try {
      if (deciding === "approve") {
        await approveIntentToAward(request.tender, { notes, lotId: request.lot_id ?? undefined });
        setToast(
          `Intent to Award issued for ${request.tender_reference_number}. The standstill period is now running and the bidders have been notified.`
        );
      } else if (deciding === "changes_requested") {
        await requestIntentToAwardChanges(request.tender, { notes, lotId: request.lot_id ?? undefined });
        setToast(`Sent back to the RBF. Nothing has been issued for ${request.tender_reference_number} yet.`);
      } else {
        await rejectIntentToAward(request.tender, { notes, lotId: request.lot_id ?? undefined });
        setToast(`Intent to Award rejected for ${request.tender_reference_number}. The RBF can propose another bidder.`);
      }
      setPending((prev) => prev.filter((r) => r.id !== request.id));
      setActive(null);
    } catch (err: any) {
      await decisionError(err, "Failed to process the decision.", request.id);
    } finally {
      setBusyId(null);
    }
  };

  const DECISION_COPY = {
    approve: {
      title: "Approve Intent to Award",
      confirm: "Approve & Issue",
      label: "Approval Notes (optional)",
      placeholder: "Add any notes for the RBF...",
      warning: "Approving is the step that issues the notice. The tender moves to Standstill, the cooling-off period starts, and every bidder is notified. This cannot be undone by editing the request.",
    },
    changes_requested: {
      title: "Request Changes",
      confirm: "Send Back to RBF",
      label: "What needs to change? (recommended)",
      placeholder: "Describe what the RBF needs to fix before resubmitting...",
      warning: "Nothing is issued. The request is closed as \"Changes Requested\" and the RBF can propose again once they have revised it.",
    },
    reject: {
      title: "Reject Intent to Award",
      confirm: "Reject",
      label: "Reason for Rejection (optional)",
      placeholder: "Explain why this bidder should not be awarded...",
      warning: "Nothing is issued. The RBF may propose a different bidder, and every request is kept in the tender's award history.",
    },
  } as const;

  return (
    <div className="space-y-6">
      {toast && (
        <div className="flex items-center justify-between gap-4 p-4 bg-emerald-50 rounded-xl border border-emerald-200">
          <p className="text-sm text-emerald-800 font-medium">{toast}</p>
          <button onClick={() => setToast(null)} className="text-emerald-600 hover:text-emerald-800">
            <X size={18} />
          </button>
        </div>
      )}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Intent to Award Approvals</h1>
          <p className="text-sm text-slate-500 mt-1">
            Nothing is issued until you approve it here — the RBF's proposal only queues a request.
          </p>
        </div>
        <button onClick={() => void load()} className="btn-secondary flex items-center gap-2" disabled={loading}>
          <RefreshCw className={loading ? "animate-spin" : ""} size={16} /> Refresh
        </button>
      </div>

      {error && <div className="p-4 bg-rose-50 rounded-xl border border-rose-200 text-sm text-rose-700">{error}</div>}

      {loading ? (
        <div className="card p-10 text-center text-sm text-slate-500">Loading pending approvals...</div>
      ) : pending.length === 0 ? (
        <div className="card p-12 text-center">
          <ShieldCheck size={40} className="mx-auto text-emerald-300 mb-3" />
          <p className="font-semibold text-slate-700">No pending intent to award approvals</p>
          <p className="text-sm text-slate-500 mt-1">
            Proposals the RBF queues from the Award panel will appear here.
          </p>
        </div>
      ) : (
        <div className="space-y-4">
          {pending.map((request) => (
            <div key={request.id} className="card p-5">
              <div className="flex flex-wrap items-start justify-between gap-4">
                <div className="space-y-1">
                  <div className="flex items-center gap-3">
                    <h3 className="font-bold text-slate-900">{request.tender_name}</h3>
                    {request.lot_name && <span className="badge bg-violet-100 text-violet-700">{request.lot_name}</span>}
                    {request.from_challenge && <span className="badge bg-orange-100 text-orange-700">Upheld challenge</span>}
                    <span className="badge bg-amber-100 text-amber-700">{request.status_label}</span>
                  </div>
                  <p className="text-xs font-mono text-slate-500">{request.tender_reference_number}</p>
                </div>
                <div className="flex flex-wrap gap-2">
                  {onOpenTender && (
                    <button onClick={() => onOpenTender(request.tender)} className="btn-secondary text-sm py-1.5">
                      View Tender
                    </button>
                  )}
                  <button
                    onClick={() => openDecision(request, "approve")}
                    disabled={busyId === request.id}
                    className="btn-primary text-sm py-1.5 bg-emerald-600 hover:bg-emerald-700 disabled:opacity-60"
                  >
                    Approve
                  </button>
                  <button
                    onClick={() => openDecision(request, "changes_requested")}
                    disabled={busyId === request.id}
                    className="btn-secondary text-sm py-1.5 border-orange-200 text-orange-700 hover:bg-orange-50 disabled:opacity-60"
                  >
                    Request Changes
                  </button>
                  <button
                    onClick={() => openDecision(request, "reject")}
                    disabled={busyId === request.id}
                    className="btn-secondary text-sm py-1.5 border-rose-200 text-rose-700 hover:bg-rose-50 disabled:opacity-60"
                  >
                    Reject
                  </button>
                </div>
              </div>

              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-4 text-sm">
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Proposed Winner</p>
                  <p className="font-medium text-slate-700 mt-0.5">{request.proposed_vendor_name || "N/A"}</p>
                </div>
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">EC Consensus</p>
                  <p className="font-medium text-slate-700 mt-0.5">
                    {request.ec_consensus === true ? "Agreed" : request.ec_consensus === false ? "Diverged" : "N/A"}
                  </p>
                </div>
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Raised By</p>
                  <p className="font-medium text-slate-700 mt-0.5">{request.requested_by_name || "N/A"}</p>
                </div>
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Requested</p>
                  <p className="font-medium text-slate-700 mt-0.5">
                    {request.requested_at ? new Date(request.requested_at).toLocaleString() : "N/A"}
                  </p>
                </div>
              </div>

              {request.ec_override_reason && (
                <div className="mt-4 p-3 bg-orange-50 border border-orange-100 rounded-lg text-sm text-orange-800">
                  <span className="font-bold">EC override: </span>
                  {request.ec_override_reason}
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {active && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl p-6 w-full max-w-md shadow-2xl">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-bold text-slate-900">{DECISION_COPY[deciding].title}</h3>
              <button onClick={() => setActive(null)} className="p-1 hover:bg-slate-100 rounded-lg">
                <X size={20} className="text-slate-500" />
              </button>
            </div>
            <p className="text-sm text-slate-600 mb-1 font-medium">
              {active.tender_name}
              {active.lot_name ? ` — ${active.lot_name}` : ""}
            </p>
            <p className="text-xs font-mono text-slate-500 mb-4">{active.tender_reference_number}</p>
            <p className="text-xs text-slate-600 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 mb-4">
              {DECISION_COPY[deciding].warning}
            </p>
            <div>
              <label className="text-sm font-bold text-slate-700 mb-2 block">{DECISION_COPY[deciding].label}</label>
              <textarea
                className="input-field min-h-[90px]"
                value={notesMap[active.id] ?? ""}
                onChange={(e) => setNotesMap((m) => ({ ...m, [active.id]: e.target.value }))}
                placeholder={DECISION_COPY[deciding].placeholder}
              />
            </div>
            <div className="flex gap-3 pt-4">
              <button onClick={() => setActive(null)} className="btn-secondary flex-1">Cancel</button>
              <button
                onClick={() => void confirmDecision()}
                disabled={busyId === active.id}
                className={`flex-1 btn-primary disabled:opacity-60 ${
                  deciding === "approve" ? "bg-emerald-600 hover:bg-emerald-700" :
                  deciding === "changes_requested" ? "bg-orange-600 hover:bg-orange-700" :
                  "bg-rose-600 hover:bg-rose-700"
                }`}
              >
                {busyId === active.id ? "Working..." : DECISION_COPY[deciding].confirm}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

